    marked = [[False] * w for _ in range(h)]

    # For every row interval, find horizontal runs whose columns all have
    # the same color throughout that interval. Such runs are solid rectangles.
    for top in range(h):
        for bottom in range(top + 4, h):
            common = []
            for c in range(w):
                value = grid[top][c]
                if all(grid[r][c] == value for r in range(top + 1, bottom + 1)):
                    common.append(value)
                else:
                    common.append(None)
            c = 0
            while c < w:
                value = common[c]
                if value is None:
                    c += 1
                    continue
                end = c + 1
                while end < w and common[end] == value:
                    end += 1
                if end - c >= 5:
                    for r in range(top, bottom + 1):
                        for cc in range(c, end):
                            marked[r][cc] = True
                c = end

    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
